∩╗┐import type { GraphQLResponse, QueryVariables } from "../../types"
import type { PaymentType } from "@/modules/types/enums/payment-type"

/** Payload inside `courseEnroll.data` after the standard API wrapper. */
export interface CourseEnrollData {
    /** URL the user should be redirected to complete checkout. */
    checkoutUrl: string
    /** Internal transaction row ID. */
    transactionId: string
    /** Payment-gateway reference ID for reconciliation. */
    referenceId: string
    /** Checkout amount in VND. */
    amount: number
    /** SePay PG only: JSON of signed fields to POST as a form to `checkoutUrl`. */
    checkoutFields?: string | null
}

/** GraphQL `CourseEnrollRequest` body. */
export interface CourseEnrollRequest {
    /** ID of the course to enroll in. */
    courseId: string
    /** Payment gateway to use (PayOS or SePay). */
    paymentType: PaymentType
    /** PayOS return URL after successful payment. */
    payosReturnUrl?: string
    /** PayOS cancel URL if user aborts checkout. */
    payosCancelUrl?: string
    /** Optional Coin-shop voucher code applied on top of the loyalty discount. */
    voucherCode?: string
    /** Pay in installments (trß║ú g├│p) over this many months (3/6/12). Omit = pay in full. Only PayOS/Sepay (VND). */
    installmentMonths?: number
}

/** Apollo variables bag for the `courseEnroll` mutation. */
export type MutateCourseEnrollVariables = QueryVariables<CourseEnrollRequest>

/** Apollo response shape for `courseEnroll`. */
export interface MutateCourseEnrollResponse {
    /** Top-level `courseEnroll` field wrapping the standard API response. */
    courseEnroll: GraphQLResponse<CourseEnrollData>
}

import type { GraphQLResponse } from "../../types"
import type {
    CommentNode,
    ReactionSummary,
    ReactionType,
} from "../../queries/types/discussion"

/**
 * GraphQL `CreateCommentRequest` body. A top-level comment must set exactly one of
 * `contentId` (a lesson question) or `courseId` (a course-general "hß╗Åi chung kh├│a"
 * question); a reply only needs `parentCommentId` (it inherits the parent's scope).
 */
export interface CreateCommentRequest {
    /** Content the comment is attached to; omit for a course-general question or a reply. */
    contentId?: string | null
    /** Course the comment is attached to (course-general question); omit for a lesson question or a reply. */
    courseId?: string | null
    /** Parent comment id when replying; null/omitted for a top-level comment. */
    parentCommentId?: string | null
    /** Raw comment body authored by the user. */
    body: string
}

/** Apollo response shape for `createComment`. */
export interface MutateCreateCommentResponse {
    /** Top-level `createComment` field wrapping the standard API response. */
    createComment: GraphQLResponse<CommentNode>
}

/** GraphQL `UpdateCommentRequest` body. */
export interface UpdateCommentRequest {
    /** Comment being edited. */
    commentId: string
    /** New body to persist. */
    body: string
}

/** Apollo response shape for `updateComment`. */
export interface MutateUpdateCommentResponse {
    /** Top-level `updateComment` field wrapping the standard API response. */
    updateComment: GraphQLResponse<CommentNode>
}

/** GraphQL `DeleteCommentRequest` body. */
export interface DeleteCommentRequest {
    /** Comment being deleted. */
    commentId: string
}

/** Payload inside `deleteComment.data`. */
export interface DeletedComment {
    /** Id of the soft-deleted comment. */
    id: string
}

/** Apollo response shape for `deleteComment`. */
export interface MutateDeleteCommentResponse {
    /** Top-level `deleteComment` field wrapping the standard API response. */
    deleteComment: GraphQLResponse<DeletedComment>
}

/** GraphQL `ReactToContentRequest` body. */
export interface ReactToContentRequest {
    /** Content being reacted to. */
    contentId: string
    /** New emotion, or null to remove the existing reaction. */
    type?: ReactionType | null
}

/** Apollo response shape for `reactToContent`. */
export interface MutateReactToContentResponse {
    /** Top-level `reactToContent` field wrapping the standard API response. */
    reactToContent: GraphQLResponse<ReactionSummary>
}

/** GraphQL `ReactToCommentRequest` body. */
export interface ReactToCommentRequest {
    /** Comment being reacted to. */
    commentId: string
    /** New emotion, or null to remove the existing reaction. */
    type?: ReactionType | null
}

/** Apollo response shape for `reactToComment`. */
export interface MutateReactToCommentResponse {
    /** Top-level `reactToComment` field wrapping the standard API response. */
    reactToComment: GraphQLResponse<ReactionSummary>
}

/** GraphQL `AcceptAnswerRequest` body (accept/clear a reply as the answer). */
export interface AcceptAnswerRequest {
    /** The reply (direct answer) to accept or unaccept. */
    commentId: string
    /** True to accept this answer (clearing any sibling), false to clear it. */
    accepted: boolean
}

/** Apollo response shape for `acceptAnswer` (success-only). */
export interface MutateAcceptAnswerResponse {
    /** Top-level `acceptAnswer` field wrapping the standard API response. */
    acceptAnswer: GraphQLResponse<boolean>
}

import type { GraphQLResponse } from "../../types"
import type { CvBlock } from "@/modules/types/entities/cv"
import type { ModelProvider } from "@/modules/api/graphql/queries/query-my-ai-settings"

/** GraphQL `RewriteCvBlockRequest` body. */
export interface RewriteCvBlockRequest {
    /** The block to rewrite (sent whole; the BE may target one item's prose within it). */
    block: CvBlock
    /**
     * `user_milestone_task_attempts.id` of the capstone this block's item is
     * `verified` against ΓÇö when set, the rewrite is grounded (RAG) on the real
     * capstone data instead of only the block's own free text.
     */
    capstoneAttemptId?: string
    /** Optional free-text steering for the rewrite (e.g. "l├ám ngß║»n gß╗ìn h╞ín"). */
    instruction?: string
    /** Pinned model name, or omitted for the Auto lane. */
    selectedModel?: string | null
    /** Provider of the pinned model, or omitted for the Auto lane. */
    selectedModelProvider?: ModelProvider | null
}

/** Payload inside `rewriteCvBlock.data` after the standard API wrapper. */
export interface RewriteCvBlockResponseData {
    /** The same block, with its prose rewritten by the AI. */
    block: CvBlock
}

/** Apollo response shape for the `rewriteCvBlock` mutation. */
export interface MutateRewriteCvBlockResponse {
    /** Top-level `rewriteCvBlock` field wrapping the standard API response. */
    rewriteCvBlock: GraphQLResponse<RewriteCvBlockResponseData>
}

import type { GraphQLResponse } from "../../types"
import type { CvBlock } from "@/modules/types/entities/cv"

/** GraphQL `SplitCvFromTextRequest` body. */
export interface SplitCvFromTextRequest {
    /** Raw pasted CvGalleryPage text (from an existing r├⌐sum├⌐) to parse into blocks. */
    text: string
}

/** Payload inside `splitCvFromText.data` after the standard API wrapper. */
export interface SplitCvFromTextResponseData {
    /** AI-parsed blocks ΓÇö NOT persisted; the caller loads these straight into the editor. */
    blocks: Array<CvBlock>
}

/** Apollo response shape for the `splitCvFromText` mutation. */
export interface MutateSplitCvFromTextResponse {
    /** Top-level `splitCvFromText` field wrapping the standard API response. */
    splitCvFromText: GraphQLResponse<SplitCvFromTextResponseData>
}

import type { GraphQLResponse } from "../../types"

/** GraphQL `StartFlashcardQuizSessionRequest` body. */
export interface StartFlashcardQuizSessionRequest {
    /** Course the quiz draws its cards from. */
    courseId: string
    /** The cards drawn for this run, in play order (1-10). */
    cardIds: Array<string>
    /**
     * Practice mode chosen at setup ("quick"|"deep") ΓÇö REQUIRED (non-null) on the
     * backend; persisted so history/stats can show it. Restored 2026-07-09 (had
     * been dropped from this type, which broke `startFlashcardQuizSession` ΓÇö
     * the backend rejects a request missing this field).
     */
    mode: string
    /** Seniority level filter chosen at setup, or null for "all levels" ΓÇö REQUIRED
     *  (nullable) on the backend; persisted so history/stats can show it. */
    level: string | null
    /**
     * Learner-chosen name for this session, set at setup ("Cß║Ñu h├¼nh luyß╗çn").
     * Optional ΓÇö omitted/blank falls back to a TIME-BASED display name derived
     * from the session's `createdAt` (see `sessionDisplayName`), never
     * random-generated.
     */
    name?: string
}

/** Payload inside `startFlashcardQuizSession.data` after the standard API wrapper. */
export interface StartFlashcardQuizSessionData {
    /** Server-issued id for this run ΓÇö used by `syncFlashcardQuizSessionProgress`,
     *  `completeFlashcardQuizSession`, and the resumable `.../quiz/[sessionId]` route. */
    sessionId: string
    /** ISO timestamp of the session's resumable-window deadline (createdAt + duration)
     *  ΓÇö drives the `WorkSessionHeader` countdown, same as Mock Interview's own `deadlineAt`. */
    deadlineAt: string
}

/** Apollo response shape for `startFlashcardQuizSession`. */
export interface MutateStartFlashcardQuizSessionResponse {
    /** Top-level `startFlashcardQuizSession` field wrapping the standard API response. */
    startFlashcardQuizSession: GraphQLResponse<StartFlashcardQuizSessionData>
}

import type { GraphQLResponse } from "../../types"

/** Deck-review scope picked in the mode modal ΓÇö `"full"` (whole deck) or `"due"` (only cards needing review). */
export type FlashcardReviewMode = "full" | "due"

/** GraphQL `StartFlashcardReviewSessionRequest` body. */
export interface StartFlashcardReviewSessionRequest {
    /** Deck this review session belongs to. */
    deckId: string
    /** The deck's card ids, in the order they will be reviewed. */
    cardIds: Array<string>
    /**
     * Which cards to persist into the session (thß║ºy 2026-07-13 "modal chß╗ìn mode"):
     * `"full"` (default) keeps the whole deck; `"due"` keeps only the cards
     * needing review (no review row yet or past due). Omit for the full deck.
     */
    mode?: FlashcardReviewMode
}

/** Payload inside `startFlashcardReviewSession.data` after the standard API wrapper. */
export interface StartFlashcardReviewSessionData {
    /** Server-issued id for this run ΓÇö used by `syncFlashcardReviewSessionProgress`,
     *  `completeFlashcardReviewSession`, and `myInProgressFlashcardReviewSession`. */
    sessionId: string
}

/** Apollo response shape for `startFlashcardReviewSession`. */
export interface MutateStartFlashcardReviewSessionResponse {
    /** Top-level `startFlashcardReviewSession` field wrapping the standard API response. */
    startFlashcardReviewSession: GraphQLResponse<StartFlashcardReviewSessionData>
}

import { createAuthApolloClient } from "../clients"
import { type QueryParams } from "../types"
import { DocumentNode, gql } from "@apollo/client"
import type { QueryAiModelsResponse } from "./types"

/** Cost/quality category of a model (mirrors backend `AiModelCategory`). */
export enum AiModelCategory {
    Low = "low",
    Medium = "medium",
    High = "high",
    EmbeddingBulk = "embedding_bulk",
    EmbeddingDoc = "embedding_doc",
}

/** Task a model is suited for (mirrors backend `AiModelTask`). Drives picker visibility. */
export enum AiModelTask {
    Chatting = "chatting",
    Grading = "grading",
    CvGenerating = "cv_generating",
    TaskGrading = "task_grading",
    ChallengeGrading = "challenge_grading",
}

const query1 = gql`
  query AiModels {
    aiModels {
      success
      message
      error
      data {
        tier
        models {
          taskKind
          label
          description
          activeModel {
            model
            provider
          }
          fallbackChain {
            model
            provider
          }
        }
        gradableModels {
          model
          provider
          category
          complimentary
          available
          supportedTasks
        }
      }
    }
  }
`

export enum QueryAiModels {
    Query1 = "query1",
}

const queryMap: Record<QueryAiModels, DocumentNode> = {
    [QueryAiModels.Query1]: query1,
}

export const queryAiModels = async ({
    query = QueryAiModels.Query1,
    headers,
    debug,
    signal,
}: Omit<QueryParams<QueryAiModels, never>, "request"> & { request?: never }) => {
    const apollo = createAuthApolloClient({
        cache: false,
        headers,
        debug,
        signal,
    })
    return apollo.query<QueryAiModelsResponse>({
        query: queryMap[query],
    })
}

import { createAuthApolloClient } from "../clients"
import type { QueryParams } from "../types"
import { DocumentNode, gql } from "@apollo/client"
import type {
    QueryAutocompleteGlobalSearchRequest,
    QueryAutocompleteGlobalSearchResponse,
} from "./types"

const query1 = gql`
  query AutocompleteGlobalSearch($request: AutocompleteGlobalSearchRequest!) {
    autocompleteGlobalSearch(request: $request) {
      success
      message
      error
      data {
        courses {
          id
          displayId
          title
          texts
          path
          isEnrolled
          isFree
          parentPath { course { id displayId } module { id displayId } content { id displayId } challenge { id displayId } }
        }
        modules {
          id
          displayId
          title
          texts
          path
          parentPath { course { id displayId } module { id displayId } content { id displayId } challenge { id displayId } }
        }
        challenges {
          id
          displayId
          title
          texts
          path
          parentPath { course { id displayId } module { id displayId } content { id displayId } challenge { id displayId } }
        }
        contents {
          id
          displayId
          title
          texts
          path
          isPremium
          parentPath { course { id displayId } module { id displayId } content { id displayId } challenge { id displayId } }
        }
        flashcardDecks {
          id
          displayId
          title
          texts
          path
          parentPath { course { id displayId } }
        }
        milestones {
          id
          displayId
          title
          texts
          path
          parentPath { course { id displayId } task { id displayId } }
        }
        milestoneTasks {
          id
          displayId
          title
          texts
          path
          parentPath { course { id displayId } }
        }
        foundations {
          id
          displayId
          title
          texts
          path
          parentPath { course { id displayId } }
        }
      }
    }
  }
`

export enum QueryAutocompleteGlobalSearch {
    Query1 = "query1",
}

const queryMap: Record<QueryAutocompleteGlobalSearch, DocumentNode> = {
    [QueryAutocompleteGlobalSearch.Query1]: query1,
}

export const queryAutocompleteGlobalSearch = async ({
    query = QueryAutocompleteGlobalSearch.Query1,
    request,
    debug,
    signal,
}: QueryParams<QueryAutocompleteGlobalSearch, QueryAutocompleteGlobalSearchRequest>) => {
    const apollo = createAuthApolloClient({
        cache: false,
        debug,
        signal,
    })

    return apollo.query<QueryAutocompleteGlobalSearchResponse>({
        query: queryMap[query],
        variables: {
            request,
        },
    })
}

